module TopModule(
    input [3:0] x,
    input [3:0] y,
    output [4:0] sum
);

    wire c0, c1, c2, c3;
    wire [3:0] s;

    // Full adder 0
    full_adder fa0(
        .a(x[0]),
        .b(y[0]),
        .c_in(1'b0),
        .s(s[0]),
        .c_out(c0)
    );

    // Full adder 1
    full_adder fa1(
        .a(x[1]),
        .b(y[1]),
        .c_in(c0),
        .s(s[1]),
        .c_out(c1)
    );

    // Full adder 2
    full_adder fa2(
        .a(x[2]),
        .b(y[2]),
        .c_in(c1),
        .s(s[2]),
        .c_out(c2)
    );

    // Full adder 3
    full_adder fa3(
        .a(x[3]),
        .b(y[3]),
        .c_in(c2),
        .s(s[3]),
        .c_out(c3)
    );

    // Output sum and overflow
    assign sum = {c3, s};

endmodule

module TopModule (
  input  [3:0] x,
  input  [3:0] y,
  output [4:0] sum
);

  wire [3:0] carry;
  wire [4:0] result;

  // First full adder
  full_adder fa1(x[0], y[0], 1'b0, result[0], carry[0]);

  // Second full adder
  full_adder fa2(x[1], y[1], carry[0], result[1], carry[1]);

  // Third full adder
  full_adder fa3(x[2], y[2], carry[1], result[2], carry[2]);

  // Fourth full adder
  full_adder fa4(x[3], y[3], carry[2], result[3], carry[3]);

  // Output carry bit
  assign sum = {carry[3], result};

endmodule

module FullAdder(input a, b, cin, output sum, cout);
  wire s1, c1, c2;
  assign s1 = a ^ b;
  assign c1 = a & b;
  assign sum = s1 ^ cin;
  assign c2 = c1 | (s1 & cin);
  assign cout = c2;
endmodule

