    full_adder fa2(.a(x[2]), .b(y[2]), .c_in(carry[1]), .sum(sum_temp[2]), .c_out(carry[2]));
    full_adder fa3(.a(x[3]), .b(y[3]), .c_in(carry[2]), .sum(sum_temp[3]), .c_out(c_out[3]));

