module TopModule (
  input [3:0] x,
  input [3:0] y,
  output [4:0] sum
);

wire [3:0] c; // carry bits
wire [4:0] s; // sum bits

assign s[0] = x[0] ^ y[0];
assign c[0] = x[0] & y[0];

generate
  genvar i;
  for (i = 1; i < 4; i = i + 1) begin : adder_loop
    assign s[i] = x[i] ^ y[i] ^ c[i-1];
    assign c[i] = (x[i] & y[i]) | (x[i] & c[i-1]) | (y[i] & c[i-1]);
  end
endgenerate

assign sum = {c[3], s};

endmodule

module TopModule(
  input [3:0] x,
  input [3:0] y,
  output reg [4:0] sum
);

  wire [3:0] c; // Carry bits

  assign sum[0] = x[0] ^ y[0];
  assign c[0] = x[0] & y[0];

  assign sum[1] = x[1] ^ y[1] ^ c[0];
  assign c[1] = (x[1] & y[1]) | (x[1] & c[0]) | (y[1] & c[0]);

  assign sum[2] = x[2] ^ y[2] ^ c[1];
  assign c[2] = (x[2] & y[2]) | (x[2] & c[1]) | (y[2] & c[1]);

  assign sum[3] = x[3] ^ y[3] ^ c[2];
  assign c[3] = (x[3] & y[3]) | (x[3] & c[2]) | (y[3] & c[2]);

  assign sum[4] = c[3]; // Overflow bit

endmodule

