module TopModule(
  input  [7:0] a,
  input  [7:0] b,
  output [7:0] s,
  output       overflow
);

  // Auxiliary wire to store the carry out of the adder
  wire carry_out;

  // Full adder for the least significant bit of s
  full_adder FA0(a[0], b[0], 1'b0, s[0], carry_out);

  // Full adders for the remaining bits of s
  genvar i;
  generate
    for (i = 1; i < 8; i = i + 1) begin : gen_adders
      full_adder FA(a[i], b[i], carry_out, s[i], carry_out);
    end
  endgenerate

  // Check for overflow
  assign overflow = (a[7] == b[7] && s[7] != a[7]) || (a[7] != b[7] && s[7] != a[7] && s[7] != b[7]);

endmodule

module TopModule (
  input [7:0] a,
  input [7:0] b,
  output [7:0] s,
  output overflow
);

  wire [7:0] sum;
  wire carry;

  // Full adder
  // This assumes that the full adder module is called FullAdder and has two inputs,
  // two outputs, and one carry input.
  FullAdder fa0(.a(a[0]), .b(b[0]), .c(1'b0), .s(sum[0]), .cout(carry));
  FullAdder fa1(.a(a[1]), .b(b[1]), .c(carry), .s(sum[1]), .cout(carry));
  FullAdder fa2(.a(a[2]), .b(b[2]), .c(carry), .s(sum[2]), .cout(carry));
  FullAdder fa3(.a(a[3]), .b(b[3]), .c(carry), .s(sum[3]), .cout(carry));
  FullAdder fa4(.a(a[4]), .b(b[4]), .c(carry), .s(sum[4]), .cout(carry));
  FullAdder fa5(.a(a[5]), .b(b[5]), .c(carry), .s(sum[5]), .cout(carry));
  FullAdder fa6(.a(a[6]), .b(b[6]), .c(carry), .s(sum[6]), .cout(carry));
  FullAdder fa7(.a(a[7]), .b(b[7]), .c(carry), .s(sum[7]), .cout(carry));

  assign s = sum;
  assign overflow = carry;

endmodule

