module TopModule (
    input clk,
    input x,
    output z
);

    // Declare intermediate signals
    wire x_ff, x_not_ff, x_not_not_ff;
    wire xor_out, and_out, or_out;

    // D flip-flops for x
    DFF_p #(
        .INIT(1'b0)
    ) x_ff_inst (
        .Q(x_ff),
        .C(clk),
        .D(x)
    );

    // D flip-flops for ~x
    DFF_p #(
        .INIT(1'b0)
    ) x_not_ff_inst (
        .Q(x_not_ff),
        .C(clk),
        .D(~x)
    );

    // D flip-flops for ~~x
    DFF_p #(
        .INIT(1'b0)
    ) x_not_not_ff_inst (
        .Q(x_not_not_ff),
        .C(clk),
        .D(~~x)
    );

    // XOR gate
    XOR2_X1 xor_inst (
        .Z(xor_out),
        .A1(x),
        .A2(x_ff)
    );

    // AND gate
    AND2_X1 and_inst (
        .Z(and_out),
        .A1(x),
        .A2(x_not_ff)
    );

    // OR gate
    OR2_X1 or_inst (
        .Z(or_out),
        .A1(x),
        .A2(x_not_not_ff)
    );

    // NOR gate
    NOR3_X1 nor_inst (
        .Z(z),
        .A1(xor_out),
        .A2(and_out),
        .A3(or_out)
    );

