    input areset,
    input train_valid,
    input train_taken,
    output reg [1:0] state
);

    // Asynchronous reset
    always @(posedge clk, posedge areset) begin
        if (areset) begin
            state <= 2'b01;
        end
        else begin
            // Increment counter if training and taken
            if (train_valid && train_taken && state < 2'b11) begin
                state <= state + 1;
            end
            // Decrement counter if training and not taken
            else if (train_valid && !train_taken && state > 2'b00) begin
                state <= state - 1;
            end
        end
    end

endmodule

