module TopModule (
  input  in,
  input  [3:0] state,
  output [3:0] next_state,
  output out
);

  wire [3:0] next_state_internal;
  assign next_state[0] = next_state_internal[0];
  assign next_state[1] = next_state_internal[1];
  assign next_state[2] = next_state_internal[2];
  assign next_state[3] = next_state_internal[3];

  // Implementation of state transition logic
  always @(*) begin
    if (state == 4'b0001) begin
      next_state_internal = {1'b0, 1'b1, 1'b0, 1'b0};
    end else if (state == 4'b0010) begin
      next_state_internal = {1'b1, 1'b0, 1'b0, 1'b0};
    end else if (state == 4'b0100) begin
      next_state_internal = {1'b0, 1'b0, 1'b1, 1'b0};
    end else if (state == 4'b1000) begin
      next_state_internal = {1'b0, 1'b1, 1'b0, 1'b1};
    end else begin
      next_state_internal = 4'b0000;
    end
  end

  // Implementation of output logic
  always @(*) begin
    if (state == 4'b0001 || state == 4'b0010) begin
      out = 1'b0;
    end else if (state == 4'b0100 || state == 4'b1000) begin
      out = 1'b1;
    end else begin
      out = 1'b0;
    end
  end

endmodule

