module TopModule(
  input  clk,
  input  areset,
  input  x,
  output reg z
);

  // Define states
  parameter A = 2'b00;
  parameter B = 2'b01;

  // Define state register and initialize to A
  reg [1:0] state;
  always @ (posedge clk or posedge areset) begin
    if (areset) begin
      state <= A;
    end else begin
      case (state)
        A: begin
          if (x == 1'b0) begin
            state <= A;
          end else begin
            state <= B;
          end
        end
        B: begin
          if (x == 1'b0) begin
            state <= B;
          end else begin
            state <= B;
          end
        end
      endcase
    end
  end

  // Define output logic
  always @ (state, x) begin
    case (state)
      A: begin
        z <= 1'b0;
      end
      B: begin
        z <= 1'b1;
      end
    endcase
  end

endmodule

module TopModule(
