    A = 2'b01,
    B = 2'b10;

  // Define the state register
  reg [1:0] state;

  // Define the output register
  reg z_reg;

  // Define the next state logic
  always @ (posedge clk) begin
    if (areset) begin
      state <= A;
    end else begin
      case (state)
        A: begin
          if (x == 1'b0) begin
            state <= A;
          end else begin
            state <= B;
          end
        end
        B: begin
          if (x == 1'b0) begin
            state <= B;
          end else begin
            state <= A;
          end
        end
      endcase
    end
  end

  // Define the output logic
  always @ (posedge clk) begin
    if (areset) begin
      z_reg <= 1'b0;
    end else begin
      case (state)
        A: begin
          z_reg <= 1'b0;
        end
        B: begin
          z_reg <= 1'b1;
        end
      endcase
    end
  end

  // Assign the output register to the output port
  assign z = z_reg;

endmodule

module TopModule(
  input  clk,
  input  areset,
  input  x,
  output z
);

