  parameter [1:0] A = 2'b01;
  parameter [1:0] B = 2'b10;

  // Define state registers
  reg [1:0] state_reg;
  reg [1:0] state_next;

  // Define output register
  reg z_reg;

  // Define next-state logic
  always @ (state_reg, x) begin
    case (state_reg)
      A: begin
        if (x == 0) begin
          state_next = A;
          z_reg = 0;
        end else begin
          state_next = B;
          z_reg = 1;
