        if (x == 0) begin
          state_next = B;
          z_reg = 1;
        end else begin
          state_next = B;
          z_reg = 0;
        end
      end
      default: begin
        state_next = A;
        z_reg = 0;
      end
    endcase
  end

  // Define output logic
  assign z = z_reg;

  // Define state register
  always @ (posedge clk, posedge areset) begin
    if (areset) begin
      state_reg <= A;
    end else begin
      state_reg <= state_next;
    end
  end

