module TopModule (
    input clk,
    input areset,
    input x,
    output reg z
);

    // Define the states of the state machine
    parameter IDLE = 2'b00;
    parameter START = 2'b01;
    parameter READ = 2'b10;

    // Define the state register and initialize it to IDLE
    reg [1:0] state = IDLE;

    // Define the input register and initialize it to 0
    reg [31:0] input_reg = 0;

    // Define the output register and initialize it to 0
    reg [31:0] output_reg = 0;

    // Define the counter for the number of input bits
    reg [5:0] counter = 0;

    // Define the 2's complement flag
    reg twos_comp = 0;

    // Define the output flag
    reg output_flag = 0;

    always @(posedge clk) begin

        // Reset the state machine
        if (areset) begin
            state <= IDLE;
            input_reg <= 0;
            output_reg <= 0;
            counter <= 0;
            twos_comp <= 0;
            output_flag <= 0;
        end

        // Wait for the first positive edge
        else if (state == IDLE) begin
            if (x == 1) begin
                state <= START;
                twos_comp <= ~x;
            end
        end

        // Read the input bits
        else if (state == START) begin
            input_reg[counter] <= x;
            counter <= counter + 1;
            if (counter == 31) begin
                state <= READ;
            end
        end

        // Calculate the 2's complement
        else if (state == READ) begin
            output_reg <= {twos_comp, input_reg};
            output_flag <= 1;
            state <= IDLE;
        end

        // Output the result
        if (output_flag) begin
            z <= output_reg[31];
            output_flag <= 0;
        end

    end

endmodule

module TopModule(
    input   clk,
    input   areset,
    input   x,
    output  z
);

reg [1:0] state;
reg [31:0] tmp;

// Sequential logic
always @(posedge clk) begin
    if (areset) begin
        state <= 2'b00;
        tmp <= 0;
    end else begin
        case (state)
            2'b00: begin // Idle state, wait for first input
                if (x == 1'b1) begin
                    state <= 2'b01;
                    tmp[0] <= 1'b1;
                end else begin
                    state <= 2'b01;
                    tmp[0] <= 1'b0;
                end
            end
            2'b01: begin // Add input to tmp
                tmp[0] <= tmp[0] ^ x;
                tmp[31:1] <= tmp[30:0];
                if (x == 1'b1) begin
                    state <= 2'b01;
                end else begin
                    state <= 2'b10;
                end
            end
            2'b10: begin // Output tmp
                z <= tmp[0];
                state <= 2'b11;
            end
            2'b11: begin // Wait for reset
                if (areset) begin
                    state <= 2'b00;
                end
            end
        endcase
    end
end

endmodule

