module TopModule(
    input  [5:0] y,
    input  w,
    output Y1,
    output Y3
);

    wire [5:0] state;

    // State output logic for the finite-state machine
    assign state[1] = y[1];
    assign state[3] = y[3];
    assign Y1 = state[1];
    assign Y3 = state[3];

    // State flip-flop inputs
    wire state_ff_in_2 = (state == 6'b000001) ? w : state[0];
    wire state_ff_in_4 = (state == 6'b000010) ? w : state[1];
    wire state_ff_in_5 = (state == 6'b000100) ? w : state[1];
    wire state_ff_in_6 = (state == 6'b001000) ? w : state[1];
    wire state_ff_in_7 = (state == 6'b010000) ? w : state[1];
    wire state_ff_in_8 = (state == 6'b100000) ? w : state[1];

    // State flip-flops
    reg [5:0] state_ff_2;
    reg [5:0] state_ff_4;
    reg [5:0] state_ff_5;
    reg [5:0] state_ff_6;
    reg [5:0] state_ff_7;
    reg [5:0] state_ff_8;

    always @(posedge w) begin
        state_ff_2 <= state_ff_in_2;
        state_ff_4 <= state_ff_in_4;
        state_ff_5 <= state_ff_in_5;
        state_ff_6 <= state_ff_in_6;
        state_ff_7 <= state_ff_in_7;
        state_ff_8 <= state_ff_in_8;
    end

    // State output logic for the state flip-flops
    assign state[0] = state_ff_2[0];
    assign state[2] = state_ff_4[2];
    assign state[4] = state_ff_6[4];

