module TopModule(
    input c,
    input d,
    output [3:0] mux_in
);

wire a, b;

assign a = c;
assign b = d;

// The 4-to-1 mux with inputs {a,b} and selector ab is a 4-to-1 mux.
// The 2-to-1 muxes for ab=00, 01, 11, and 10 are also 4-to-1 muxes.
// We can use as many 2-to-1 muxes as required, but using as few as
// possible, and as required by the Karnaugh map.

// ab=00 is connected to mux_in[0], so we use a 2-to-1 mux.
// The 2-to-1 mux takes as input {a,b} and ab=00 to select between a
// and b. The output of the 2-to-1 mux is connected to mux_in[0].
wire ab00;
wire ab01;
wire ab11;
wire ab10;

assign ab00 = a&~b;
assign ab01 = b;
assign ab11 = a;
assign ab10 = ~a;

// ab=01 is connected to mux_in[1], so we use a 2-to-1 mux.
// The 2-to-1 mux takes as input {a,b} and ab=01 to select between a
// and b. The output of the 2-to-1 mux is connected to mux_in[1].
wire ab01_mux_out;

assign ab01_mux_out = ~(a&b);

// ab=11 is connected to mux_in[2], so we use a 2-to-1 mux.
// The 2-to-1 mux takes as input {a,b} and ab=11 to select between a
// and b. The output of the 2-to-1 mux is connected to mux_in[2].
wire ab11_mux_out;

assign ab11_mux_out = ~(a|b);

// ab=10 is connected to mux_in[3], so we use a 2-to-1 mux.
// The 2-to-1 mux takes as input {a,b} and ab=10 to select between a
// and b. The output of the 2-to-1 mux is connected to mux_in[3].
wire ab10_mux_out;

assign ab10_mux_out = ~(a^b);

// We use a 4-to-1 mux to select between {ab00_mux_out, ab01_mux_out,
// ab11_mux_out, ab10_mux_out} based on {a,b}. The output of the 4-to-1
// mux is connected to mux_in.
assign mux_in[0] = ab00_mux_out;
assign mux_in[1] = ab01_mux_out;
assign mux_in[2] = ab11_mux_out;
assign mux_in[3] = ab10_mux_out;

endmodule

