                next_state = in ? 2'b10 : 2'b01;
                out = 1'b0;
            end
            2'b10: begin
                next_state = in ? 2'b00 : 2'b11;
                out = 1'b0;
            end
            2'b11: begin
                next_state = in ? 2'b01 : 2'b10;
                out = 1'b1;
            end
        endcase
    end

