module TopModule (
    input r,
    input L,
    input clk,
    output reg q
);

    reg [1:0] mux_out;
    wire [1:0] q_in;
    wire r_in;

    // Instantiate flipflop module three times
    full_module ff1 (
        .r(r),
        .L(L),
        .clk(clk),
        .q(q_in[0])
    );
    full_module ff2 (
        .r(r),
        .L(L),
        .clk(clk),
        .q(q_in[1])
    );
    full_module ff3 (
        .r(r),
        .L(L),
        .clk(clk),
        .q(q_in[2])
    );

    // 2-to-1 multiplexer
    assign mux_out[0] = L ? r_in : q_in[0];
    assign mux_out[1] = L ? r_in : q_in[1];
    assign mux_out[2] = L ? r_in : q_in[2];

    always @(posedge clk) begin
        q <= mux_out;
    end

endmodule

