  reg [99:0] shift_out;

  always @(posedge clk) begin
    if (load) begin
      shift_reg <= data;
    end else begin
      case (ena)
        2'b01: begin // rotate right by one bit
          shift_out <= shift_reg[99];
          shift_reg <= {shift_reg[98:0], shift_out};
        end
        2'b10: begin // rotate left by one bit
          shift_out <= shift_reg[0];
          shift_reg <= {shift_out, shift_reg[99:1]};
        end
        2'b00, 2'b11: begin // do not rotate
          shift_reg <= shift_reg;
        end
      endcase
    end
  end

  assign q = shift_reg;

