  // Define the output variables
  reg out_B, out_A;

  // Define the state machine
  always @ (posedge clk) begin
    if (reset) begin
      current_state <= B;
      next_state <= B;
      out_B <= 1'b1;
      out_A <= 1'b0;
    end
    else begin
      current_state <= next_state;
      case (current_state)
        B: begin
          if (in == 1'b0) begin
            next_state <= A;
            out_B <= 1'b0;
            out_A <= 1'b1;
          end
          else begin
            next_state <= B;
            out_B <= 1'b1;
            out_A <= 1'b0;
