          if (in == 1'b0) begin
            next_state <= B;
            out_B <= 1'b1;
            out_A <= 1'b0;
          end
          else begin
            next_state <= A;
            out_B <= 1'b0;
            out_A <= 1'b1;
          end
        end
      endcase
    end
  end

  // Assign the output to the corresponding output variable
  assign out = (current_state == B) ? out_B : out_A;

