    assign history_shift_in = {predict_taken, predict_history_reg[30:0]};

    // Update predict history register
    always @(posedge clk) begin
        if (areset) begin
            predict_history_reg <= 32'h0;
        end else begin
            if (predict_valid) begin
                predict_history_reg <= history_shift_in;
