    wire [31:0] history_out;
    reg [31:0] predict_history_reg;

    // Reset the history register on positive edge of areset
    always @(posedge areset) begin
        history_reg <= 32'h0;
        predict_history_reg <= 32'h0;
    end

    // Shift in predict_taken on positive edge of clk
    always @(posedge clk) begin
        if (predict_valid) begin
            history_reg <= {history_reg[29:0], predict_taken};
