    end

    // Load history register on positive edge of clk
    always @(posedge clk) begin
        if (train_mispredicted) begin
            history_reg <= {train_history, train_taken};
        end
    end

    // Shift out history_reg onto predict_history_reg on positive edge of clk
    assign history_out = {history_reg[29:0], history_reg[31]};
    always @(posedge clk) begin
        predict_history_reg <= history_out;
    end

    // Output predict_history
    assign predict_history = predict_history_reg;

endmodule

module TopModule(
  input  wire  clk,
  input  wire  areset,
  input  wire  in,
  output wire  out
);

  // Define the states of the FSM
  localparam A = 2'b00;
  localparam B = 2'b01;
  localparam C = 2'b10;
  localparam D = 2'b11;

  // Define the current and next states of the FSM
  reg [1:0] state, next_state;

  // Define the output of the FSM
  reg out_reg;

  // Define the state transition logic
  always @(posedge clk) begin
    if (areset) begin
      state <= A;
      next_state <= B;
      out_reg <= 1'b0;
    end else begin
      state <= next_state;
      case (state)
        A: begin
          if (in) begin
            next_state <= B;
            out_reg <= 1'b0;
          end else begin
            next_state <= C;
            out_reg <= 1'b0;
          end
        end
        B: begin
          if (in) begin
            next_state <= B;
            out_reg <= 1'b0;
          end else begin
            next_state <= D;
            out_reg <= 1'b0;
          end
        end
        C: begin
          if (in) begin
            next_state <= C;
            out_reg <= 1'b0;
          end else begin
            next_state <= A;
            out_reg <= 1'b0;
          end
        end
        D: begin
          if (in) begin
            next_state <= C;
            out_reg <= 1'b1;
          end else begin
            next_state <= B;
            out_reg <= 1'b0;
          end
        end
      endcase
    end
  end

  // Assign the output of the FSM
  assign out = out_reg;

endmodule

module TopModule (
