    output reg out
);

  parameter A = 2'b00;
  parameter B = 2'b01;
  parameter C = 2'b10;
  parameter D = 2'b11;

  reg [1:0] state, next_state;

  always @(posedge clk or negedge areset) begin
    if (!areset) begin
        state <= A;
    end else begin
        case(state)
            A: begin
                if (in) begin
                    next_state <= B;
                    out <= 1'b0;
                end else begin
                    next_state <= C;
                    out <= 1'b0;
                end
            end
            B: begin
                if (in) begin
