                end else begin
                    next_state <= B;
                    out <= 1'b0;
                end
            end
            C: begin
                if (in) begin
                    next_state <= D;
                    out <= 1'b0;
                end else begin
                    next_state <= C;
                    out <= 1'b0;
                end
            end
            D: begin
                if (in) begin
                    next_state <= C;
                    out <= 1'b1;
                end else begin
                    next_state <= B;
                    out <= 1'b0;
                end
            end
        endcase
    end
  end

