    input  clk,
    input  areset,
    input  in,
    output out
);

  reg [1:0] state, next_state;
  parameter [1:0] A = 2'b00, B = 2'b01, C = 2'b10, D = 2'b11;

  always @ (posedge clk) begin
    if (areset) begin
      state <= A;
    end else begin
      state <= next_state;
    end
  end

  always @ (*) begin
    case (state)
      A: begin
        next_state = in ? B : A;
        out = 1'b0;
      end
      B: begin
        next_state = in ? C : B;
        out = 1'b0;
      end
      C: begin
        next_state = in ? A : D;
        out = 1'b0;
      end
      D: begin
        next_state = in ? C : B;
        out = 1'b1;
      end
    endcase
  end

endmodule

