    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= A;
        end else begin
            case (state)
                A: begin
                    state <= in ? B : A;
                end
                B: begin
                    state <= in ? C : B;
                end
                C: begin
                    state <= in ? D : A;
                end
                D: begin
                    state <= in ? B : C;
                end
            endcase
        end
    end

    assign out = (state == D) ? 1'b1 : 1'b0;

endmodule

