            state <= A;
        end else begin
            case (state)
                A: begin
                    if (in) begin
                        state <= B;
                    end else begin
                        state <= C;
                    end
                end
                B: begin
                    if (in) begin
                        state <= D;
                    end else begin
                        state <= B;
                    end
                end
