module TopModule(
  input clk,
  input areset,
  input in,
  output reg out
);

  // Define the states
  parameter A = 2'b00;
  parameter B = 2'b01;
  parameter C = 2'b10;
  parameter D = 2'b11;

  // Define the state registers
  reg [1:0] state_reg = 2'b00;
  reg [1:0] state_next;

  // Define the output registers
  reg out_reg = 1'b0;
  reg out_next;

  // Define the state transition table
  always @(*) begin
    case(state_reg)
      A: begin
        out_next = 1'b0;
        if(in == 1'b0) begin
          state_next = B;
        end else begin
          state_next = C;
        end
      end
      B: begin
        out_next = 1'b0;
        if(in == 1'b0) begin
          state_next = B;
        end else begin
          state_next = D;
        end
      end
      C: begin
        out_next = 1'b0;
        if(in == 1'b0) begin
          state_next = A;
        end else begin
          state_next = D;
        end
      end
      D: begin
        out_next = 1'b1;
        if(in == 1'b0) begin
          state_next = C;
        end else begin
          state_next = B;
        end
      end
    endcase
  end

  // Define the state and output registers
  always @(posedge clk) begin
    if(areset) begin
      state_reg <= A;
      out_reg <= 1'b0;
    end else begin
      state_reg <= state_next;
      out_reg <= out_next;
    end
  end

  // Assign the output
  assign out = out_reg;

endmodule

module TopModule(
    input  clk,
    input  areset,
    input  in,
    output out
);

    parameter [1:0] STATE_A = 2'b00, STATE_B = 2'b01, STATE_C = 2'b10, STATE_D = 2'b11;

    reg [1:0] state, next_state;
    reg out_reg;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= STATE_A;
            next_state <= STATE_B;
            out_reg <= 1'b0;
        end else begin
            state <= next_state;
            case (state)
                STATE_A: begin
                    next_state = in ? STATE_B : STATE_C;
                    out_reg <= 1'b0;
                end
                STATE_B: begin
                    next_state = in ? STATE_B : STATE_D;
                    out_reg <= 1'b0;
                end
                STATE_C: begin
                    next_state = in ? STATE_B : STATE_A;
                    out_reg <= 1'b0;
                end
                STATE_D: begin
                    next_state = in ? STATE_B : STATE_C;
                    out_reg <= 1'b1;
                end
            endcase
        end
    end

    assign out = out_reg;

endmodule

