        next_state = (in == 1'b0) ? 2'b00 : 2'b11;
      end
      2'b11: begin // state D
        next_state = (in == 1'b0) ? 2'b10 : 2'b01;
      end
    endcase
  end

  assign out = out_reg;

endmodule

