module TopModule(
    input clk,
    input reset,
    input x,
    output reg z
);

    reg [2:0] y;

    always @(posedge clk) begin
        if (reset) begin
            y <= 3'b000;
            z <= 1'b0;
        end
        else begin
            case (y)
                3'b000: if (x) y <= 3'b001; else y <= 3'b000;
                3'b001: if (x) y <= 3'b100; else y <= 3'b010;
                3'b010: if (x) y <= 3'b001; else y <= 3'b000;
                3'b011: if (x) y <= 3'b010; else y <= 3'b001;
                3'b100: if (x) y <= 3'b100; else y <= 3'b011;
            endcase

            case (y)
                3'b000, 3'b001: z <= 1'b0;
                3'b010, 3'b011, 3'b100: z <= 1'b1;
            endcase
        end
    end

endmodule

module TopModule (
  input  wire         clk,
  input  wire         reset,
  input  wire         x,
  output wire         z
);

  // State assignment
  parameter S0 = 3'b000;
  parameter S1 = 3'b001;
  parameter S2 = 3'b010;
  parameter S3 = 3'b011;
  parameter S4 = 3'b100;

  // State registers
  reg [2:0] state_reg;
  reg [2:0] state_next;

  // Output z
  assign z = (state_reg == S3) ? 1'b1 : 1'b0;

  // State transition logic
  always @(posedge clk) begin
    if (reset) begin
      state_reg <= S0;
    end else begin
      state_reg <= state_next;
    end
  end

  // Next state logic
  always @(state_reg, x) begin
    case (state_reg)
      S0: state_next = (x == 1'b0) ? S1 : S0;
      S1: state_next = (x == 1'b0) ? S2 : S0;
      S2: state_next = (x == 1'b0) ? S3 : S0;
      S3: state_next = (x == 1'b0) ? S0 : S4;
      S4: state_next = (x == 1'b0) ? S0 : S4;
      default: state_next = S0;
    endcase
  end

endmodule

module TopModule (
  input  clk,
  input  reset,
  input  x,
  output reg z
);

  // Declare state variable
  reg [2:0] state;

  // Synchronous reset
  always @(posedge clk) begin
    if (reset) begin
      state <= 3'b000;
      z <= 1'b0;
    end
    else begin
      // Determine next state based on input
      case ({state, x})
        5'b00000: state <= 3'b000;
        5'b00001, 5'b00100: state <= 3'b001;
        5'b00010: state <= 3'b010;
        5'b00011: state <= 3'b001;
        5'b00110: state <= 3'b010;
        5'b01000, 5'b01100: state <= 3'b011;
        default: state <= 3'b000;
      endcase

      // Determine output based on state
      case (state)
        3'b000: z <= 1'b0;
        3'b001, 3'b010: z <= 1'b0;
        3'b011: z <= 1'b1;
        default: z <= 1'b0;
      endcase
    end
  end

endmodule

