module TopModule(
    input clk,
    input areset,
    input bump_left,
    input bump_right,
    output reg walk_left,
    output reg walk_right
);

    // Define the states
    parameter LEFT = 1'b0;
    parameter RIGHT = 1'b1;

    // Define the current state and next state registers
    reg current_state;
    reg next_state;

    // Initialize the state registers
    initial begin
        current_state = LEFT;
        next_state = LEFT;
    end

    // Define the Moore machine
    always @ (posedge clk, posedge areset) begin
        if (areset) begin
            current_state <= LEFT;
        end
        else begin
            current_state <= next_state;
        end
    end

    // Define the next state logic
    always @ (*) begin
        case (current_state)
            LEFT: begin
                walk_left <= 'b1;
                walk_right <= 'b0;
                if (bump_left == 1'b1) begin
                    next_state <= RIGHT;
                end
                else begin
                    next_state <= LEFT;
                end
            end
            RIGHT: begin
                walk_left <= 'b0;
                walk_right <= 'b1;
                if (bump_right == 1'b1) begin
                    next_state <= LEFT;
                end
                else begin
                    next_state <= RIGHT;
                end
            end
        endcase
    end
endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    output walk_left,
    output walk_right
);

    reg [1:0] state;
    parameter S_LEFT = 2'b00, S_RIGHT = 2'b01;

    always @(posedge clk) begin
        if (areset) begin
            state <= S_LEFT;
        end else begin
            case(state)
                S_LEFT: if (bump_right) state <= S_RIGHT;
                S_RIGHT: if (bump_left) state <= S_LEFT;
            endcase
        end
    end

    assign walk_left = (state == S_LEFT) ? 1'b1 : 1'b0;
    assign walk_right = (state == S_RIGHT) ? 1'b1 : 1'b0;

endmodule

