    parameter CHECK_1 = 2'b01;
    parameter CHECK_2 = 2'b10;
    parameter DONE = 2'b11;

    // Define the state register and wire
    reg [1:0] state;
    wire [1:0] next_state;

    // Define the output register and wire
    reg done_reg;
    wire done_wire;

    // Define the input register and wire
    reg [7:0] in_reg;

