    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            done_reg <= 1'b0;
            in_reg <= 8'b0;
        end else begin
            state <= next_state;
            done_reg <= done_wire;
            in_reg <= in;
        end
    end

    // Define the state transitions
    always @(*) begin
        case (state)
            IDLE: begin
                if (in_reg[3] == 1'b1) begin
                    next_state = CHECK_1;
                end else begin
                    next_state = IDLE;
                end
            end
            CHECK_1: begin
                if (in_reg[3] == 1'b0) begin
                    next_state = CHECK_2;
                end else begin
                    next_state = CHECK_1;
                end
            end
            CHECK_2: begin
                if (in_reg[3] == 1'b1) begin
                    next_state = DONE;
                end else begin
                    next_state = CHECK_2;
                end
            end
            DONE: begin
                next_state = IDLE;
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end

    // Define the output logic
    assign done_wire = (state == DONE) ? 1'b1 : 1'b0;
    assign done = done_reg;

