    localparam FIRST_BYTE = 2'b01;
    localparam SECOND_BYTE = 2'b10;
    localparam THIRD_BYTE = 2'b11;

    // Define the state register and next state
    reg [1:0] current_state, next_state;

    // Define the output register and next output
    reg done_reg, done_next;

    // Define the data register and next data
    reg [7:0] data_reg, data_next;

    // Define the count register and next count
    reg [1:0] count_reg, count_next;

    // Define the done signal
    assign done = done_reg;

    // The sequential logic
    always @(posedge clk) begin
        if (reset) begin
            current_state <= IDLE;
            done_reg <= 1'b0;
            data_reg <= 8'b0;
            count_reg <= 2'b0;
        end else begin
            current_state <= next_state;
            done_reg <= done_next;
            data_reg <= data_next;
            count_reg <= count_next;
        end
    end

    // The combinational logic
    always @(*) begin
        // Default values
        next_state = current_state;
        done_next = done_reg;
        data_next = data_reg;
        count_next = count_reg;

        case (current_state)
