            FIRST_BYTE: begin
                next_state = SECOND_BYTE;
                data_next = in;
                count_next = count_reg + 1;
            end

            SECOND_BYTE: begin
                next_state = THIRD_BYTE;
                data_next = in;
                count_next = count_reg + 1;
            end

            THIRD_BYTE: begin
                next_state = IDLE;
