                    if (s == 1) begin
                        state <= B;
                        counter <= 2'b00;
                    end else begin
                        state <= A;
                    end
                end
                B: begin
                    // Check w for three clock cycles
                    if (w == 1) begin
                        counter <= counter + 1;
