                        // Reset counter and move to next state
                        counter <= 2'b00;
                        state <= C;
                    end else begin
                        // Move to next state
                        state <= B;
                    end
                end
                C: begin
                    // Output value for one clock cycle
                    z <= output_reg;
                    // Move to next state
                    state <= D;
                end
                D: begin
                    // Stay in D until w goes high
                    if (w == 1) begin
                        state <= B;
                        counter <= 2'b00;
                    end else begin
                        state <= D;
