    reg [1:0] current_state;
    reg [1:0] next_state;
    reg [1:0] x_history;
    reg [1:0] y_history;

    // State machine logic
    always @(posedge clk, negedge resetn) begin
        if (~resetn) begin
            current_state <= A;
            f <= 1;
            g <= 0;
            x_history <= 2'b00;
            y_history <= 2'b00;
        end else begin
            current_state <= next_state;
            case (current_state)
                A: begin
                    f <= 1;
                    g <= 0;
                    if (x == 1) begin
                        x_history <= {x_history[0], x};
                    end else begin
                        x_history <= 2'b00;
                    end
                end
                B: begin
                    f <= 0;
                    g <= 0;
                    if (x == 1) begin
                        x_history <= {x_history[0], x};
                    end else begin
                        x_history <= 2'b00;
                    end
                end
                C: begin
                    f <= 1;
                    g <= 1;
                    if (y == 1) begin
                        y_history <= {y_history[0], y};
                    end else begin
                        y_history <= 2'b00;
                    end
                end
                D: begin
                    f <= 0;
                    g <= 1;
                    if (y == 1) begin
                        y_history <= {y_history[0], y};
                    end else begin
                        y_history <= 2'b00;
                    end
                end
            endcase
        end
    end

    // State machine next state logic
    always @(*) begin
        case (current_state)
            A: begin
                if (resetn == 1'b0) begin
                    next_state <= A;
                end else if (x_history == 2'b111) begin
                    next_state <= C;
                end else begin
                    next_state <= B;
                end
