            B: begin
                if (resetn == 1'b0) begin
                    next_state <= A;
                end else if (x_history == 2'b111) begin
                    next_state <= C;
                end else begin
                    next_state <= D;
                end
            end
            C: begin
                if (resetn == 1'b0) begin
                    next_state <= A;
                end else if (y_history == 2'b11) begin
                    next_state <= D;
                end else begin
                    next_state <= C;
                end
            end
            D: begin
                if (resetn == 1'b0) begin
                    next_state <= A;
                end else if (y_history == 2'b11) begin
                    next_state <= D;
                end else begin
                    next_state <= C;
                end
            end
        endcase
    end

