module TopModule(
    input clk,
    input areset,
    input bump_left,
    input bump_right,
    input ground,
    output reg walk_left,
    output reg walk_right,
    output reg aaah
);

    parameter WALKING_LEFT = 2'b00;
    parameter WALKING_RIGHT = 2'b01;
    parameter FALLING = 2'b10;

    reg [1:0] state;
    reg [1:0] next_state;

    always @(posedge clk) begin
        if (areset) begin
            state <= WALKING_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
        end else begin
            state <= next_state;
            walk_left <= (state == WALKING_LEFT);
            walk_right <= (state == WALKING_RIGHT);
            aaah <= (state == FALLING);
        end
    end

    always @(*) begin
        case (state)
            WALKING_LEFT: begin
                if (bump_right) begin
                    next_state <= WALKING_RIGHT;
                end else if (ground == 0) begin
                    next_state <= FALLING;
                end else begin
                    next_state <= WALKING_LEFT;
                end
            end
            WALKING_RIGHT: begin
                if (bump_left) begin
                    next_state <= WALKING_LEFT;
                end else if (ground == 0) begin
                    next_state <= FALLING;
                end else begin
                    next_state <= WALKING_RIGHT;
                end
            end
            FALLING: begin
                if (ground == 1) begin
                    if (bump_left) begin
                        next_state <= WALKING_LEFT;
                    end else if (bump_right) begin
                        next_state <= WALKING_RIGHT;
                    end else begin
                        next_state <= WALKING_LEFT;
                    end
                end else begin
                    next_state <= FALLING;
                end
            end
        endcase
    end

endmodule

module TopModule(
