    output reg         aaah
);

    // Define the states of the Moore state machine
    localparam WALK_LEFT   = 1'b0;
    localparam WALK_RIGHT  = 1'b1;

    // Define the state register
    reg [0:0] state_reg;

    // Define the next state logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state_reg <= WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
        end else begin
            case (state_reg)
                WALK_LEFT: begin
                    if (bump_left) begin
                        state_reg <= WALK_RIGHT;
                        walk_left <= 1'b0;
                        walk_right <= 1'b1;
                    end else if (bump_right) begin
                        state_reg <= WALK_RIGHT;
                        walk_left <= 1'b0;
                        walk_right <= 1'b1;
                    end else if (!ground) begin
                        aaah <= 1'b1;
                    end else begin
                        walk_left <= 1'b1;
                        walk_right <= 1'b0;
                    end
                end
                WALK_RIGHT: begin
                    if (bump_right) begin
                        state_reg <= WALK_LEFT;
                        walk_left <= 1'b1;
                        walk_right <= 1'b0;
                    end else if (bump_left) begin
                        state_reg <= WALK_LEFT;
                        walk_left <= 1'b1;
                        walk_right <= 1'b0;
                    end else if (!ground) begin
                        aaah <= 1'b1;
                    end else begin
                        walk_right <= 1'b1;
                        walk_left <= 1'b0;
                    end
                end
            endcase
        end
    end

    // Define the state output logic
    always @(*) begin
        if (state_reg == WALK_LEFT) begin
            walk_left <= 1'b1;
            walk_right <= 1'b0;
        end else begin
            walk_left <= 1'b0;
            walk_right <= 1'b1;
        end
    end

