  input  bump_right,
  input  ground,
  output walk_left,
  output walk_right,
  output aaah
);

  reg [1:0] state;
  reg next_state;
  assign walk_left = (state == 2'b01);
  assign walk_right = (state == 2'b10);

  always @(posedge clk) begin
    if (areset) begin
      state <= 2'b01;
    end else begin
      state <= next_state;
    end
  end

  always @(*) begin
    case (state)
      2'b01: next_state = bump_right ? 2'b10 : bump_left ? 2'b10 : ground ? 2'b01 : 2'b00;
      2'b10: next_state = bump_left ? 2'b01 : bump_right ? 2'b01 : ground ? 2'b10 : 2'b00;
      2'b00: next_state = ground ? state : ~(bump_left | bump_right);
    endcase
  end

  assign aaah = state == 2'b00;

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    output walk_left,
    output walk_right,
    output aaah
);

    // Define the states of the Moore State Machine
    localparam IDLE = 2'b00;
    localparam WALK_LEFT = 2'b01;
    localparam WALK_RIGHT = 2'b10;
    localparam FALL = 2'b11;

    // Define the state register and next state logic
    reg [1:0] state_reg, state_next;
    always @(posedge clk, posedge areset) begin
        if (areset) begin
            state_reg <= WALK_LEFT;
        end else begin
            state_reg <= state_next;
        end
    end

    // Define the output logic based on the state
    assign walk_left = (state_reg == WALK_LEFT);
    assign walk_right = (state_reg == WALK_RIGHT);
    assign aaah = (state_reg == FALL);

    // Define the state transition logic
    always @(*) begin
        case (state_reg)
            IDLE: begin
                if (bump_left) begin
                    state_next = WALK_RIGHT;
                end else if (bump_right) begin
                    state_next = WALK_LEFT;
                end else if (ground) begin
                    state_next = WALK_LEFT;
                end else begin
                    state_next = IDLE;
                end
            end
            WALK_LEFT: begin
                if (bump_left) begin
                    state_next = WALK_RIGHT;
                end else if (bump_right) begin
                    state_next = WALK_LEFT;
                end else if (ground) begin
                    state_next = IDLE;
                end else begin
                    state_next = WALK_LEFT;
                end
            end
            WALK_RIGHT: begin
                if (bump_left) begin
                    state_next = WALK_RIGHT;
                end else if (bump_right) begin
                    state_next = WALK_LEFT;
                end else if (ground) begin
                    state_next = IDLE;
                end else begin
                    state_next = WALK_RIGHT;
                end
            end
            FALL: begin
                if (ground) begin
                    if (bump_left) begin
                        state_next = WALK_RIGHT;
                    end else if (bump_right) begin
                        state_next = WALK_LEFT;
                    end else begin
                        state_next = IDLE;
                    end
                end else begin
                    state_next = FALL;
                end
            end
        endcase
    end

    // Define the state transition logic for falling
    always @(posedge clk, posedge areset) begin
        if (areset) begin
            state_reg <= WALK_LEFT;
        end else if (state_reg == FALL && !ground) begin
            if (bump_left) begin
                state_reg <= WALK_RIGHT;
            end else if (bump_right) begin
                state_reg <= WALK_LEFT;
            end else if (ground) begin
                state_reg <= IDLE;
            end else begin
                state_reg <= FALL;
            end
        end
    end

endmodule

module TopModule (
