    input  wire bump_left,
    input  wire bump_right,
    input  wire ground,
    output wire walk_left,
    output wire walk_right,
    output wire aaah
);

    // Define the states of the finite state machine
    localparam STATE_LEFT = 2'b00;
    localparam STATE_RIGHT = 2'b01;
    localparam STATE_FALLING = 2'b10;

    // Define the Moore output signals
    wire falling = (state == STATE_FALLING);
    wire walking_left = (state == STATE_LEFT);
    wire walking_right = (state == STATE_RIGHT);

    // Define the state register and next state logic
    reg [1:0] state;
    reg [1:0] next_state;
    always @(posedge clk) begin
        if (areset) begin
            state <= STATE_LEFT;
        end else begin
            state <= next_state;
        end
    end
    always @(*) begin
        case (state)
            STATE_LEFT: begin
                if (bump_right) begin
                    next_state = STATE_RIGHT;
                end else if (ground) begin
                    next_state = STATE_LEFT;
                end else if (bump_left) begin
                    next_state = STATE_FALLING;
                end else begin
                    next_state = STATE_LEFT;
                end
            end
            STATE_RIGHT: begin
                if (bump_left) begin
                    next_state = STATE_LEFT;
                end else if (ground) begin
                    next_state = STATE_RIGHT;
                end else if (bump_right) begin
                    next_state = STATE_FALLING;
                end else begin
                    next_state = STATE_RIGHT;
                end
            end
            STATE_FALLING: begin
                if (ground) begin
                    next_state = (bump_left) ? STATE_LEFT : STATE_RIGHT;
                end else begin
                    next_state = STATE_FALLING;
                end
            end
            default: begin
                next_state = STATE_LEFT;
            end
        endcase
    end

    // Define the Moore output logic
    assign walk_left = walking_left;
    assign walk_right = walking_right;
    assign aaah = falling;

endmodule

module TopModule (
