  assign next_state[0] = (state[0] &  state[1]) | ((state[0] & state[2]) | (state[1] & state[2]));
  assign next_state[1] = (state[0] & ~state[1]) | (~state[0] & state[2]);
  assign next_state[2] = (state[1] & ~state[2]) | (~state[0] & state[1]);
  assign next_state[3] = ~state[0] & ~state[1] & state[2];
  assign next_state[4] = (state[4] & state[5]) | ((state[4] & state[6]) | (state[5] & state[6]));
  assign next_state[5] = (state[4] & ~state[5]) | (~state[4] & state[6]);
  assign next_state[6] = (state[5] & ~state[6]) | (~state[4] & state[5]);
  assign next_state[7] = ~state[4] & ~state[5] & state[6];
  assign next_state[8] = (state[8] & state[9]) | ((state[8] & ~state[9]) | (state[9] & ~state[8]));
  assign next_state[9] = (state[8] & ~state[9]) | (~state[8] & state[9]);

  // Output logic
  assign out1 = (state[1] & ~state[2]) | (~state[0] & state[1]);
  assign out2 = state[9] & state[8];

