module TopModule (
  input in,
  input [9:0] state,
  output [9:0] next_state,
  output out1,
  output out2
);

  // State encoding
  localparam S0 = 10'b0000000001;
  localparam S1 = 10'b0000000010;
  localparam S2 = 10'b0000000100;
  localparam S3 = 10'b0000001000;
  localparam S4 = 10'b0000010000;
  localparam S5 = 10'b0000100000;
  localparam S6 = 10'b0001000000;
  localparam S7 = 10'b0010000000;
  localparam S8 = 10'b0100000000;
  localparam S9 = 10'b1000000000;

  // Output logic
  assign out1 = (state == S7) ? 1 : 0;
  assign out2 = (state == S7) ? 1 : 0;

  // State transition logic
  always @* begin
    next_state = state;  // Default to staying in current state

    case (state)
      S0: next_state = (in == 1) ? S1 : S0;
      S1: next_state = (in == 1) ? S2 : S0;
      S2: next_state = (in == 1) ? S3 : S0;
      S3: next_state = (in == 1) ? S4 : S0;
      S4: next_state = (in == 1) ? S5 : S0;
      S5: next_state = (in == 1) ? S6 : S8;
      S6: next_state = (in == 1) ? S7 : S9;
      S7: next_state = (in == 1) ? S7 : S0;
      S8: next_state = (in == 1) ? S1 : S0;
      S9: next_state = (in == 1) ? S1 : S0;
      default: next_state = S0;  // Invalid state, default to S0
    endcase
  end

endmodule

