module TopModule (
    input clk,
    input load,
    input [255:0] data,
    output [255:0] q
);

    reg [255:0] grid;
    reg [15:0] row_count;
    integer i, j;
    wire [15:0] neighbors;

    // Load the data into the grid on the next clock edge
    always @(posedge clk) begin
        if (load) begin
            grid <= data;
        end
    end

    // Update the grid state on every clock cycle
    always @(posedge clk) begin
        for (i = 0; i < 16; i = i + 1) begin
            for (j = 0; j < 16; j = j + 1) begin
                neighbors = grid[(i-1+16)%16+(j+16)%16*16] + grid[(i+1)%16+(j+16)%16*16] + grid[(i+1)%16+(j-1+16)%16*16] + grid[(i-1+16)%16+(j-1+16)%16*16] +
                            grid[(i+2)%16+(j+16)%16*16] + grid[(i-2+16)%16+(j+16)%16*16] + grid[(i-2+16)%16+(j-1+16)%16*16] + grid[(i+2)%16+(j-1+16)%16*16];
                if (neighbors == 2) begin
                    grid[i+j*16] <= grid[i+j*16];
                end else if (neighbors == 3) begin
                    grid[i+j*16] <= 1;
                end else begin
                    grid[i+j*16] <= 0;
                end
            end
        end
        row_count <= row_count + 1;
    end

    // Output the current grid state
    assign q = grid;

endmodule

module TopModule(
   input clk,
   input load,
   input [255:0] data,
   output [255:0] q
);

   reg [255:0] grid;
   wire [255:0] next_grid;
   wire [3:0] neighbours;

   // Initialize the grid
   always @(posedge clk) begin
      if (load) begin
         grid <= data;
      end else begin
         grid <= next_grid;
      end
   end

   // Count the neighbours of each cell
   genvar i, j;
   generate
      for (i = 0; i < 16; i = i + 1) begin: row
         for (j = 0; j < 16; j = j + 1) begin: col
            assign neighbours = grid[(i-1+16)%16*16+(j-1+16)%16] +
                               grid[(i-1+16)%16*16+j] +
                               grid[(i-1+16)%16*16+(j+1)%16] +
                               grid[(i+1)%16*16+(j-1+16)%16] +
                               grid[(i+1)%16*16+(j+1)%16];
            assign next_grid[i*16+j] = (neighbours == 2) ? grid[i*16+j] :
                                       (neighbours == 3) ? 1 :
                                       (neighbours >= 4) ? 0 :
                                       grid[i*16+j];
         end
      end
   endgenerate

   assign q = next_grid;

endmodule

module TopModule(
    input clk,
    input load,
    input [255:0] data,
    output [255:0] q
);

reg [255:0] q_reg;
wire [255:0] q_next;

// Calculate the number of neighbours for each cell
wire [255:0] neighbour_count;
genvar i, j;
generate
    for (i = 0; i < 16; i = i + 1) begin : row_loop
        for (j = 0; j < 16; j = j + 1) begin : col_loop
            wire [2:0] neighbour_count_local;
            assign neighbour_count_local[0] = q_reg[(i+15)%16*16 + (j+15)%16];
            assign neighbour_count_local[1] = q_reg[(i+15)%16*16 + j];
            assign neighbour_count_local[2] = q_reg[(i+15)%16*16 + (j+1)%16];
            assign neighbour_count_local[3] = q_reg[(i+14)%16*16 + (j+15)%16];
            assign neighbour_count_local[4] = q_reg[(i+14)%16*16 + j];
            assign neighbour_count_local[5] = q_reg[(i+14)%16*16 + (j+1)%16];
            assign neighbour_count_local[6] = q_reg[(i+1)%16*16 + (j+15)%16];
            assign neighbour_count_local[7] = q_reg[(i+1)%16*16 + j];
            assign neighbour_count_local[8] = q_reg[(i+1)%16*16 + (j+1)%16];
            assign neighbour_count[(i*16)+j] = neighbour_count_local;
        end
    end
endgenerate

// Determine the next state of each cell
assign q_next = {q_reg[255:128], q_reg[127:0], q_reg[255:128]};
genvar k;
generate
    for (k = 0; k < 256; k = k + 1) begin : cell_loop
        always @(neighbour_count[k])
            case (neighbour_count[k])
                3'b000,
                3'b001,
                3'b010,
                3'b101,
                3'b110,
                3'b111,
                3'b0000: q_next[k] = 0;
                3'b0011,
                3'b0110,
                3'b1001,
                3'b1010,
                3'b1100,
                3'b00011,
                3'b00101,
                3'b01001,
                3'b10001,
                3'b10110,
                3'b11010: q_next[k] = 1;
                default: q_next[k] = 0;
            endcase
    end
endgenerate

// Output the next state after two clock cycles
assign q = q_next;

// Load data into q at the next clock edge
always @(posedge clk) begin
    if (load) begin
        q_reg <= data;
    end else begin
        q_reg <= q_next;
    end
end

endmodule

