    localparam START_BIT = 2'b01;
    localparam DATA_BITS = 2'b10;

    // Define state registers
    reg [1:0] state;
    reg [7:0] byte_buffer;

    // Define counters
    reg [2:0] bit_counter;

    // Define asynchronous reset
    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            byte_buffer <= 8'b0;
            bit_counter <= 3'b0;
            out_byte <= 8'b0;
            done <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (in == 1'b0) begin
                        state <= START_BIT;
                        bit_counter <= 1'b0;
                    end
                end
                START_BIT: begin
                    if (bit_counter == 3'd7) begin
                        if (in == 1'b1) begin
                            state <= DATA_BITS;
