                            byte_buffer <= byte_buffer << 1;
                        end else begin
                            state <= IDLE;
                            byte_buffer <= 8'b0;
                            bit_counter <= 1'b0;
                        end
                    end else begin
                        byte_buffer <= byte_buffer << 1;
                        byte_buffer[0] <= in;
                        bit_counter <= bit_counter + 1'b1;
                    end
                end
                DATA_BITS: begin
                    if (bit_counter == 3'd7) begin
                        if (in == 1'b1) begin
                            state <= IDLE;
                            byte_buffer <= byte_buffer << 1;
                            byte_buffer[0] <= in;
                            out_byte <= byte_buffer;
                            done <= 1'b1;
                            bit_counter <= 1'b0;
                        end else begin
                            state <= IDLE;
                            byte_buffer <= 8'b0;
                            bit_counter <= 1'b0;
                        end
                    end else begin
                        byte_buffer <= byte_buffer << 1;
                        byte_buffer[0] <= in;
                        bit_counter <= bit_counter + 1'b1;
                    end
                end
                default: begin
                    state <= IDLE;
                    byte_buffer <= 8'b0;
