module TopModule(
    input clk,
    input in,
    input reset,
    output [7:0] out_byte,
    output done
);

    // Define states
    localparam IDLE = 2'b00;
    localparam START = 2'b01;
    localparam DATA = 2'b10;
    localparam STOP = 2'b11;

    // Define internal signals
    reg [1:0] state;
    reg [7:0] data_reg;
    reg [2:0] bit_count;
    reg done_reg;
    reg [7:0] out_byte_reg;

    // Synchronous reset
    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            data_reg <= 8'b0;
            bit_count <= 3'b0;
            done_reg <= 1'b0;
            out_byte_reg <= 8'b0;
        end
    end

    // Finite state machine
    always @(posedge clk) begin
        case (state)
            IDLE:
                if (in == 1'b0) begin
                    state <= START;
                    bit_count <= 3'b0;
                    data_reg <= 8'b0;
                end
            START:
                if (in == 1'b1 && bit_count == 3'b0) begin
                    state <= DATA;
                    bit_count <= bit_count + 1;
                end
            DATA:
                if (bit_count < 3'b11) begin
                    data_reg <= {data_reg[6:0], in};
                    bit_count <= bit_count + 1;
                end
                else begin
                    state <= STOP;
                    bit_count <= 3'b0;
                end
            STOP:
                if (in == 1'b0) begin
                    out_byte_reg <= data_reg;
                    done_reg <= 1'b1;
                    state <= IDLE;
                end
        endcase
    end

    // Output
    assign out_byte = out_byte_reg;
    assign done = done_reg;

