module TopModule (
    input  wire clk,
    input  wire in,
    input  wire reset,
    output wire [7:0] out_byte,
    output wire done
);

    // State machine states
    localparam STATE_IDLE = 2'b00;
    localparam STATE_START_BIT = 2'b01;
    localparam STATE_DATA_BITS = 2'b10;
    localparam STATE_STOP_BIT = 2'b11;

    // State machine control signals
    reg [1:0] state, next_state;
    reg [7:0] data_byte;
    reg done_int;

    // Synchronous reset
    always @(posedge clk) begin
        if (reset) begin
            state <= STATE_IDLE;
            data_byte <= 8'b0;
            done_int <= 1'b0;
        end
        else begin
            state <= next_state;
            if (done_int) begin
                data_byte <= 8'b0;
                done_int <= 1'b0;
            end
        end
    end

    // State machine logic
    always @(*) begin
        next_state = state;
        case (state)
            STATE_IDLE: begin
                if (in == 1'b0) begin
                    next_state = STATE_START_BIT;
                end
            end
            STATE_START_BIT: begin
                next_state = STATE_DATA_BITS;
            end
            STATE_DATA_BITS: begin
                if (!in) begin
                    next_state = STATE_STOP_BIT;
                    data_byte[0] = in;
                end
                else begin
                    next_state = STATE_DATA_BITS;
                    data_byte = {in, data_byte[7:1]};
                end
            end
            STATE_STOP_BIT: begin
                if (in == 1'b1) begin
                    next_state = STATE_IDLE;
                    done_int = 1'b1;
                end
                else begin
                    next_state = STATE_STOP_BIT;
                end
            end
        endcase
    end

    assign out_byte = data_byte;
    assign done = done_int;

endmodule

