    parameter START = 2'b01;
    parameter DATA = 2'b10;
    parameter STOP = 2'b11;

    reg [1:0] state, next_state;
    reg [3:0] count;

    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            count <= 0;
            done <= 0;
        end
        else begin
            state <= next_state;
            if (state == START) begin
                count <= 0;
            end
            else if (state == DATA) begin
                count <= count + 1;
            end
            else if (state == STOP) begin
                done <= 1;
            end
        end
    end

    always @(state or in) begin
        case (state)
            IDLE: begin
                if (in == 0) begin
                    next_state <= START;
                end
                else begin
                    next_state <= IDLE;
                end
            end
            START: begin
                if (in == 1) begin
                    next_state <= DATA;
                end
                else begin
                    next_state <= START;
                end
            end
            DATA: begin
                if (count == 7) begin
                    next_state <= STOP;
                end
                else begin
                    next_state <= DATA;
                end
            end
            STOP: begin
                if (in == 1) begin
                    next_state <= IDLE;
                end
                else begin
                    next_state <= STOP;
                end
            end
        endcase
    end

    always @(posedge clk) begin
        if (state == DATA) begin
            out_byte <= {out_byte[6:0], in};
        end
    end

