      state_reg <= A;
    end else begin
      state_reg <= state_next;
    end
  end

  always @(*) begin
    case (state_reg)
      A: begin
        if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b0) begin
          state_next = A;
        end else if (r[0] == 1'b1) begin
          state_next = B;
        end else if (r[0] == 1'b0 && r[1] == 1'b1) begin
          state_next = C;
        end else if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b1) begin
