        end else begin
          state_next = state_reg;
        end
      end
      B: begin
        if (r[0] == 1'b1) begin
          state_next = B;
        end else if (r[0] == 1'b0) begin
          state_next = A;
        end else begin
          state_next = state_reg;
        end
      end
      C: begin
        if (r[1] == 1'b1) begin
          state_next = C;
        end else if (r[1] == 1'b0) begin
          state_next = A;
        end else begin
          state_next = state_reg;
        end
      end
      D: begin
        if (r[0] == 1'b1 || r[1] == 1'b1 || r[2] == 1'b1) begin
          state_next = D;
        end else begin
          state_next = A;
        end
      end
      default: begin
        state_next = A;
      end
    endcase
  end

  // Define outputs
  always @(*) begin
    case (state_reg)
      A: begin
        g = 3'b000;
      end
      B: begin
        g = (r[0] == 1'b1) ? 3'b001 : 3'b000;
      end
      C: begin
        g = (r[1] == 1'b1) ? 3'b010 : 3'b000;
      end
      D: begin
        g = 3'b111;
      end
