    reg [2:0] state;

    // State table
    always @* begin
        case (state)
            A: begin
                if (r[0] && !r[1] && !r[2]) begin
                    // Device 0 requests access
                    g = 3'b001;
                    state = B;
                end
                else if (!r[0] && r[1] && !r[2]) begin
