                    g = 3'b100;
                    state = D;
                end
                else begin
                    // No requests
                    g = 3'b000;
                    state = A;
                end
            end
            B: begin
                if (r[0]) begin
                    // Device 0 continues to have access
                    g = 3'b001;
                    state = B;
                end
                else begin
                    // Device 0 releases access
                    g = 3'b000;
                    state = A;
                end
            end
            C: begin
                if (r[1]) begin
                    // Device 1 continues to have access
                    g = 3'b010;
                    state = C;
