                else begin
                    // Device 1 releases access
                    g = 3'b000;
                    state = A;
                end
            end
            D: begin
                if (r[2]) begin
                    // Device 2 continues to have access
                    g = 3'b100;
                    state = D;
                end
                else begin
                    // Device 2 releases access
                    g = 3'b000;
                    state = A;
                end
            end
        endcase
    end

    // Reset logic
    always @(posedge clk) begin
        if (!resetn) begin
            state <= A;
