module TopModule(
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output shift_ena,
    output counting,
    output done
);

    // State machine states
    typedef enum {
        IDLE,
        SHIFT,
        WAIT_FOR_COUNTING,
        WAIT_FOR_DONE,
        WAIT_FOR_ACK
    } state_t;

    // State machine registers
    state_t state;
    reg [2:0] shift_reg;
    reg shift_ena_reg;
    reg counting_reg;
    reg done_reg;

    // State machine next state and output logic
    always @(posedge clk) begin
        if (reset) begin
            // Synchronous reset
            state <= IDLE;
            shift_reg <= 3'b0;
            shift_ena_reg <= 1'b0;
            counting_reg <= 1'b0;
            done_reg <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (shift_ena_reg) begin
                        state <= SHIFT;
                    end else if (data == 1'b1 && shift_reg == 3'b110) begin
                        state <= WAIT_FOR_COUNTING;
                        shift_ena_reg <= 1'b1;
                    end else begin
                        shift_reg <= {shift_reg[1:0], data};
                    end
                end
                SHIFT: begin
                    if (shift_reg == 3'b1101) begin
                        state <= WAIT_FOR_COUNTING;
                        counting_reg <= 1'b1;
                    end else begin
                        shift_reg <= {shift_reg[1:0], data};
                    end
                end
                WAIT_FOR_COUNTING: begin
                    if (done_counting) begin
                        state <= WAIT_FOR_DONE;
                        done_reg <= 1'b1;
                    end
                end
                WAIT_FOR_DONE: begin
                    if (ack) begin
                        state <= WAIT_FOR_ACK;
                        done_reg <= 1'b0;
                    end
                end
                WAIT_FOR_ACK: begin
                    if (~ack) begin
                        state <= IDLE;
                        shift_ena_reg <= 1'b0;
                        counting_reg <= 1'b0;
                    end
                end
            endcase
        end
    end

    // Output assignments
    assign shift_ena = shift_ena_reg;
    assign counting = counting_reg;
    assign done = done_reg;

