module TopModule (
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output shift_ena,
    output counting,
    output done
);

    // Define constants
    localparam PATTERN = 4'b1101;
    localparam TIMEOUT_VALUE = 8'd4;

    // Define states
    enum {
        IDLE,
        SHIFT_IN,
        WAIT_FOR_COUNTING,
        NOTIFY_USER,
        WAIT_FOR_ACK
    } state, next_state;

    // Define signals
    wire pattern_found;
    reg [3:0] shift_register;
    reg [7:0] timeout_count;
    reg shift_ena_reg;
    reg counting_reg;
    reg done_reg;

    // Instantiate pattern detector
    pattern_detector #(PATTERN) detector (.clk(clk), .reset(reset), .data(data), .pattern_found(pattern_found));

    // State machine
    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Output logic
    assign shift_ena = shift_ena_reg;
    assign counting = counting_reg;
    assign done = done_reg;

    // Next state logic
    always @* begin
        shift_ena_reg = 1'b0;
        counting_reg = 1'b0;
        done_reg = 1'b0;
        next_state = state;

        case (state)
            IDLE: begin
                if (pattern_found) begin
                    next_state = SHIFT_IN;
                end
            end

            SHIFT_IN: begin
                if (timeout_count == TIMEOUT_VALUE) begin
                    next_state = WAIT_FOR_COUNTING;
                end else begin
                    shift_ena_reg = 1'b1;
                    next_state = SHIFT_IN;
                end
            end

            WAIT_FOR_COUNTING: begin
                if (done_counting) begin
                    next_state = NOTIFY_USER;
                end else begin
                    counting_reg = 1'b1;
                    next_state = WAIT_FOR_COUNTING;
                end
            end

            NOTIFY_USER: begin
                done_reg = 1'b1;
                next_state = WAIT_FOR_ACK;
            end

            WAIT_FOR_ACK: begin
                if (ack) begin
                    next_state = IDLE;
                end else begin
                    next_state = WAIT_FOR_ACK;
                end
            end
        endcase
    end

    // Shift register
    always @(posedge clk) begin
        if (reset) begin
            shift_register <= 4'b0;
        end else if (shift_ena_reg) begin
            shift_register <= {shift_register[2:0], data};
        end
    end

    // Timeout counter
    always @(posedge clk) begin
        if (reset) begin
            timeout_count <= 8'd0;
        end else begin
            if (shift_ena_reg) begin
                timeout_count <= 8'd0;
            end else begin
                timeout_count <= timeout_count + 1;
            end
        end
    end

endmodule

module TopModule(
    input clk,
    input reset,
    input data,
    input done_counting,
    input ack,
    output reg shift_ena,
    output reg counting,
    output reg done
);

parameter PATTERN = 13; // 1101

reg [2:0] state;
reg [2:0] state_next;
reg [2:0] pattern_shift_reg;
reg [2:0] pattern_shift_next;

always @(posedge clk) begin
    if (reset) begin
        pattern_shift_reg <= 3'b0;
        shift_ena <= 1'b0;
        counting <= 1'b0;
        done <= 1'b0;
        state <= IDLE;
    end else begin
        pattern_shift_reg <= pattern_shift_next;
        shift_ena <= shift_ena_next;
        counting <= counting_next;
        done <= done_next;
        state <= state_next;
    end
end

always @(*) begin
    pattern_shift_next = {pattern_shift_reg[1:0], data};
    shift_ena_next = shift_ena;
    counting_next = counting;
    done_next = done;
    state_next = state;

    case (state)
        IDLE: begin
            if (pattern_shift_reg == PATTERN) begin
                shift_ena_next = 1'b1;
                state_next = WAIT_FOR_SHIFT;
            end
        end
        WAIT_FOR_SHIFT: begin
            if (shift_ena) begin
                shift_ena_next = 1'b0;
                counting_next = 1'b1;
                state_next = WAIT_FOR_COUNTING;
            end
        end
        WAIT_FOR_COUNTING: begin
            if (done_counting) begin
                counting_next = 1'b0;
                done_next = 1'b1;
                state_next = WAIT_FOR_ACK;
            end
        end
        WAIT_FOR_ACK: begin
            if (ack) begin
                done_next = 1'b0;
                state_next = IDLE;
            end
        end
    endcase
end

endmodule

module TopModule (
    input clk,
    input reset,
    input data,
    input done_counting,
    input ack,
    output reg shift_ena,
    output reg counting,
    output reg done
);

    // Finite-state machine states
    parameter IDLE = 2'b00;
    parameter SHIFT = 2'b01;
    parameter COUNT = 2'b10;
    parameter DONE = 2'b11;

    // State and data registers
    reg [1:0] state;
    reg [3:0] shift_reg;
    reg [3:0] pattern;

    // State machine
    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            shift_reg <= 4'b0;
            pattern <= 4'b1101;
            shift_ena <= 1'b0;
            counting <= 1'b0;
            done <= 1'b0;
        end
        else begin
            case (state)
                IDLE: begin
                    if (data == pattern[0]) begin
                        shift_reg <= {shift_reg[2:0], data};
                        if (shift_reg == pattern) begin
                            shift_ena <= 1'b1;
                            state <= SHIFT;
                        end
                    end
                    else begin
                        shift_ena <= 1'b0;
                    end
                end
                SHIFT: begin
                    shift_ena <= 1'b0;
                    state <= COUNT;
                    counting <= 1'b1;
                end
                COUNT: begin
                    if (done_counting) begin
                        counting <= 1'b0;
                        state <= DONE;
                        done <= 1'b1;
                    end
                    else begin
                        counting <= 1'b1;
                    end
                end
                DONE: begin
                    if (ack) begin
                        state <= IDLE;
                        done <= 1'b0;
                    end
                end
            endcase
        end
    end
endmodule

module TopModule(
  input clk,
