  reg [3:0] shift_reg;
  reg [1:0] pattern;
  reg [3:0] duration;
  reg shift_ena_reg;

  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      shift_reg <= 4'b0;
      pattern <= 4'b1101;
      duration <= 4'b0;
      shift_ena_reg <= 1'b0;
    end else begin
      case (state)
        IDLE: begin
          if (data == pattern[3]) begin
            state <= SHIFT_PATTERN;
            shift_reg <= {data, shift_reg[3:1]};
          end
        end
        SHIFT_PATTERN: begin
          if (shift_reg == pattern) begin
            state <= SHIFT_DURATION;
            shift_ena_reg <= 1'b1;
          end else if (data == pattern[0]) begin
            shift_reg <= {data, shift_reg[3:1]};
          end
        end
        SHIFT_DURATION: begin
          if (done_counting) begin
            state <= IDLE;
            shift_ena_reg <= 1'b0;
            duration <= {shift_reg[0], shift_reg[3:1]};
            done <= 1'b1;
          end else if (shift_ena_reg) begin
            shift_ena <= 1'b1;
            counting <= 1'b1;
          end else if (ack) begin
            done <= 1'b0;
          end
        end
      endcase
    end
  end

