module TopModule (
    input clk,
    input reset,
    input data,
    input done_counting,
    input ack,
    output shift_ena,
    output counting,
    output done
);

    // Define the states of the state machine
    localparam IDLE = 2'b00;
    localparam SHIFT = 2'b01;
    localparam WAIT_COUNTING = 2'b10;
    localparam NOTIFY = 2'b11;

    // Define the state and next_state signals
    reg [1:0] state, next_state;

    // Define the shift_ena and counting signals
    reg shift_ena_reg, counting_reg;
    wire shift_ena, counting;

    // Define the done signal
    reg done_reg;
    wire done;

    // Define the registers to store the 4 bits of the pattern
    reg [3:0] pattern_reg;

    // Define the pattern to detect
    localparam PATTERN = 4'b1101;

    // Define the output assignments
    assign shift_ena = shift_ena_reg;
    assign counting = counting_reg;
    assign done = done_reg;

    // Define the state machine
    always @ (posedge clk) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Define the next state logic
    always @ (*) begin
        case (state)
            IDLE: begin
                if (pattern_reg == PATTERN) begin
                    next_state = SHIFT;
                end else begin
                    next_state = IDLE;
                end
            end
            SHIFT: begin
                next_state = WAIT_COUNTING;
            end
            WAIT_COUNTING: begin
                if (done_counting) begin
                    next_state = NOTIFY;
                end else begin
                    next_state = WAIT_COUNTING;
                end
            end
            NOTIFY: begin
                if (ack) begin
                    next_state = IDLE;
                end else begin
                    next_state = NOTIFY;
                end
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end

    // Define the output logic
    always @ (*) begin
        case (state)
            IDLE: begin
                shift_ena_reg = 0;
                counting_reg = 0;
                done_reg = 0;
            end
            SHIFT: begin
                shift_ena_reg = 1;
                counting_reg = 0;
                done_reg = 0;
            end
            WAIT_COUNTING: begin
                shift_ena_reg = 0;
                counting_reg = 1;
                done_reg = 0;
            end
            NOTIFY: begin
                shift_ena_reg = 0;
                counting_reg = 0;
                done_reg = 1;
            end
            default: begin
                shift_ena_reg = 0;
                counting_reg = 0;
                done_reg = 0;
            end
        endcase
    end

    // Define the pattern shift register
    always @ (posedge clk) begin
        if (reset) begin
            pattern_reg <= 4'b0;
        end else if (shift_ena_reg) begin
            pattern_reg <= {pattern_reg[2:0], data};
        end
