module TopModule(
    input clk, reset, data, done_counting, ack,
    output shift_ena, counting, done
);

    // Define state machine states
    localparam IDLE = 2'b00;
    localparam WAIT_FOR_SHIFT = 2'b01;
    localparam COUNTER_ACTIVE = 2'b10;
    localparam TIMER_ACTIVE = 2'b11;

    // Define state machine input and output variables
    reg [1:0] state;
    reg [1:0] next_state;
    reg shift_ena_temp;
    reg counting_temp;
    reg done_temp;

    // Define state machine state logic
    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            shift_ena_temp <= 1'b0;
            counting_temp <= 1'b0;
            done_temp <= 1'b0;
        end else begin
            state <= next_state;
            shift_ena_temp <= shift_ena;
            counting_temp <= counting;
            done_temp <= done;
        end
    end

    // Define state machine next state logic
    always @(*) begin
        case (state)
            IDLE: begin
                if (data) begin
                    next_state <= WAIT_FOR_SHIFT;
                end else begin
                    next_state <= IDLE;
                end
            end
            WAIT_FOR_SHIFT: begin
                if (shift_ena_temp) begin
                    next_state <= COUNTER_ACTIVE;
                end else begin
                    next_state <= WAIT_FOR_SHIFT;
                end
            end
            COUNTER_ACTIVE: begin
                if (done_counting) begin
                    next_state <= TIMER_ACTIVE;
                end else begin
                    next_state <= COUNTER_ACTIVE;
                end
            end
            TIMER_ACTIVE: begin
                if (ack) begin
                    next_state <= IDLE;
                end else begin
                    next_state <= TIMER_ACTIVE;
                end
            end
        endcase
    end

    // Define state machine output logic
    assign shift_ena = (state == WAIT_FOR_SHIFT) ? 1'b1 : 1'b0;
    assign counting = (state == COUNTER_ACTIVE) ? 1'b1 : 1'b0;
    assign done = (state == TIMER_ACTIVE) ? 1'b1 : 1'b0;

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output shift_ena,
    output counting,
    output done
);

// States
parameter IDLE        = 2'b00;
parameter SHIFT       = 2'b01;
parameter COUNTING    = 2'b10;
parameter DONE        = 2'b11;

// Registers
reg [1:0] state;
reg [2:0] shift_reg;
reg [2:0] count_reg;
reg ack_reg;

// Wires
wire pattern_detected;
wire shift_ena_wire;
wire counting_wire;
wire done_wire;
wire ack_wire;
wire done_counting_wire;

// Detect the pattern 1101
assign pattern_detected = (shift_reg == 3'b110);

// State machine
always @(posedge clk) begin
    if (reset) begin
        state <= IDLE;
        shift_reg <= 3'b0;
        count_reg <= 3'b0;
        ack_reg <= 1'b0;
    end else begin
        case (state)
            IDLE: begin
                if (pattern_detected) begin
                    state <= SHIFT;
                    shift_reg <= 3'b0;
                    count_reg <= 3'b0;
                    ack_reg <= 1'b0;
                end
            end
            SHIFT: begin
                if (shift_ena_wire) begin
                    shift_reg <= {shift_reg[1:0], data};
                    count_reg <= {count_reg[1:0], 1'b0};
                    ack_reg <= 1'b0;
                end else if (count_reg == 3'b111) begin
                    state <= COUNTING;
                    count_reg <= 3'b0;
                    ack_reg <= 1'b0;
                end
            end
            COUNTING: begin
                if (done_counting_wire) begin
                    state <= DONE;
                    count_reg <= 3'b0;
                    ack_reg <= 1'b0;
                end else if (count_reg == 3'b111) begin
                    count_reg <= 3'b0;
                    if (ack_wire) begin
                        ack_reg <= 1'b1;
                    end
                end
            end
            DONE: begin
                if (ack_wire) begin
                    state <= IDLE;
                    count_reg <= count_reg + 1;
                    ack_reg <= 1'b0;
                end else if (count_reg == 3'b111) begin
                    ack_reg <= 1'b1;
                end
            end
        endcase
    end
end

// Outputs
assign shift_ena = shift_ena_wire;
assign counting = counting_wire;
assign done = done_wire;
assign ack = ack_wire;
assign done_counting_wire = done_counting;

// Assign outputs based on state
assign shift_ena_wire = (state == SHIFT);
assign counting_wire = (state == COUNTING);
assign done_wire = (state == DONE);
assign ack_wire = (state == DONE) && ack_reg;

endmodule

module TopModule (
    input clk,
    input reset,
    input data,
    input done_counting,
    input ack,
    output reg shift_ena,
    output reg counting,
    output reg done
);

// Define the states of the FSM
parameter IDLE = 2'b00;
parameter WAIT_FOR_DATA = 2'b01;
parameter WAIT_FOR_COUNTERS = 2'b10;

// Define the state register and next state logic
reg [1:0] state, next_state;
always @(posedge clk) begin
    if (reset) begin
        state <= IDLE;
    end else begin
        state <= next_state;
    end
end

// Define the output logic for the FSM
always @(state or data or done_counting or ack) begin
    case (state)
        IDLE: begin
            shift_ena <= 1'b0;
            counting <= 1'b0;
            done <= 1'b0;
            if (data == 1'b1) begin
                next_state = WAIT_FOR_DATA;
            end else begin
                next_state = IDLE;
            end
        end
        WAIT_FOR_DATA: begin
            shift_ena <= 1'b1;
            counting <= 1'b0;
            done <= 1'b0;
            next_state = WAIT_FOR_COUNTERS;
        end
        WAIT_FOR_COUNTERS: begin
            shift_ena <= 1'b0;
            counting <= 1'b1;
            done <= 1'b0;
            if (done_counting) begin
                next_state = IDLE;
            end else begin
                next_state = WAIT_FOR_COUNTERS;
            end
        end
        default: begin
            shift_ena <= 1'b0;
            counting <= 1'b0;
            done <= 1'b0;
            next_state = IDLE;
        end
    endcase
end

endmodule

module TopModule(
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // Define state type and state encoding
    localparam STATE_WALK_LEFT = 2'b00;
    localparam STATE_WALK_RIGHT = 2'b01;
    localparam STATE_FALL = 2'b10;
    localparam STATE_DIG = 2'b11;

    // Define output encoding
    assign walk_left = (state == STATE_WALK_LEFT);
    assign walk_right = (state == STATE_WALK_RIGHT);
    assign aaah = (state == STATE_FALL);
    assign digging = (state == STATE_DIG);

    // Define next state logic
    reg [1:0] state;
    always @(posedge clk, posedge areset) begin
        if (areset) begin
            state <= STATE_WALK_LEFT;
        end else begin
            case (state)
                STATE_WALK_LEFT: begin
                    if (bump_right) begin
                        state <= STATE_WALK_RIGHT;
                    end else if (bump_left) begin
                        state <= STATE_WALK_LEFT;
                    end else if (dig) begin
                        state <= STATE_DIG;
                    end else if (ground == 0) begin
                        state <= STATE_FALL;
                    end else begin
                        state <= STATE_WALK_LEFT;
                    end
                end
                STATE_WALK_RIGHT: begin
                    if (bump_left) begin
                        state <= STATE_WALK_LEFT;
                    end else if (bump_right) begin
                        state <= STATE_WALK_RIGHT;
                    end else if (dig) begin
                        state <= STATE_DIG;
                    end else if (ground == 0) begin
                        state <= STATE_FALL;
                    end else begin
                        state <= STATE_WALK_RIGHT;
                    end
                end
                STATE_FALL: begin
                    if (bump_left) begin
                        state <= STATE_WALK_LEFT;
                    end else if (bump_right) begin
                        state <= STATE_WALK_RIGHT;
                    end else if (ground == 1) begin
                        state <= STATE_WALK_RIGHT;
                    end else begin
                        state <= STATE_FALL;
                    end
                end
                STATE_DIG: begin
                    if (ground == 0) begin
                        state <= STATE_FALL;
                    end else if (ground == 1) begin
                        state <= STATE_WALK_RIGHT;
                    end else begin
                        state <= STATE_DIG;
                    end
                end
            endcase
        end
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    reg [1:0] state;
    reg [1:0] next_state;
    wire falling;

    // Define states
    localparam IDLE_LEFT = 2'b00;
    localparam WALK_RIGHT = 2'b01;
    localparam WALK_LEFT = 2'b10;
    localparam FALLING = 2'b11;

    // Define next state logic
    always @* begin
        case(state)
            IDLE_LEFT: begin
                if (bump_right) next_state = WALK_RIGHT;
                else if (bump_left) next_state = WALK_LEFT;
                else if (dig) next_state = FALLING;
                else next_state = IDLE_LEFT;
            end
            WALK_RIGHT: begin
                if (ground == 0) next_state = FALLING;
                else if (bump_left) next_state = WALK_LEFT;
                else if (bump_right) next_state = WALK_RIGHT;
                else if (dig) next_state = FALLING;
                else next_state = WALK_RIGHT;
            end
            WALK_LEFT: begin
                if (ground == 0) next_state = FALLING;
                else if (bump_right) next_state = WALK_RIGHT;
                else if (bump_left) next_state = WALK_LEFT;
                else if (dig) next_state = FALLING;
                else next_state = WALK_LEFT;
            end
            FALLING: begin
                if (ground) next_state = WALK_LEFT;
                else next_state = FALLING;
            end
        endcase
    end

    // Define output logic
    assign falling = (state == FALLING);
    assign walk_left = (state == WALK_LEFT);
    assign walk_right = (state == WALK_RIGHT);
    assign aaah = falling;
    assign digging = (state == FALLING) && ground;

    // Register state
    always @(posedge clk) begin
        if (areset) begin
            state <= IDLE_LEFT;
        end else begin
            state <= next_state;
        end
    end

endmodule

module TopModule(
  input  clk,
