  output reg digging
);

  // Define the states of the Moore machine
  parameter WALK_LEFT  = 2'b00;
  parameter WALK_RIGHT = 2'b01;
  parameter FALL       = 2'b10;

  // Define the state register and initialize to WALK_LEFT
  reg [1:0] state = WALK_LEFT;

  // Define the next state logic
  always @ (posedge clk) begin
    if (areset) begin
      state <= WALK_LEFT;
    end else begin
      case (state)
        WALK_LEFT: begin
          if (bump_right) begin
            state <= WALK_RIGHT;
          end else if (bump_left && ground) begin
            state <= FALL;
          end else if (dig) begin
            state <= FALL;
          end
        end
        WALK_RIGHT: begin
          if (bump_left) begin
            state <= WALK_LEFT;
          end else if (bump_right && ground) begin
            state <= FALL;
          end else if (dig) begin
            state <= FALL;
          end
        end
