    localparam WALK_LEFT = 2'b01;
    localparam WALK_RIGHT = 2'b10;
    localparam FALL = 2'b11;

    // Define the state register and next state logic
    reg [1:0] state, next_state;
    always @(posedge clk, posedge areset) begin
        if (areset) begin
            state <= WALK_LEFT;
        end else begin
            state <= next_state;
        end
    end

    // Define the Moore output logic
    assign walk_left = (state == WALK_LEFT) ? 1'b1 : 1'b0;
    assign walk_right = (state == WALK_RIGHT) ? 1'b1 : 1'b0;
    assign aaah = (state == FALL) ? 1'b1 : 1'b0;
    assign digging = (state == WALK_LEFT && ground && dig) ? 1'b1 : 1'b0;

    // Define the next state logic
    always @(*) begin
        case (state)
            IDLE: begin
                if (ground) begin
                    next_state = WALK_LEFT;
                end else begin
                    next_state = FALL;
                end
            end
            WALK_LEFT: begin
                if (bump_left || ground) begin
                    next_state = WALK_RIGHT;
                end else if (bump_right) begin
                    next_state = WALK_LEFT;
                end else if (!ground) begin
                    next_state = FALL;
                end else if (dig) begin
                    next_state = WALK_LEFT;
                end else begin
                    next_state = state;
                end
            end
            WALK_RIGHT: begin
                if (bump_right || ground) begin
                    next_state = WALK_LEFT;
                end else if (bump_left) begin
                    next_state = WALK_RIGHT;
                end else if (!ground) begin
                    next_state = FALL;
                end else if (dig) begin
                    next_state = WALK_RIGHT;
                end else begin
                    next_state = state;
                end
            end
            FALL: begin
                if (ground) begin
                    next_state = (dig) ? WALK_LEFT : state;
                end else if (bump_left || bump_right) begin
                    next_state = FALL;
                end else begin
                    next_state = IDLE;
                end
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end

    // Define the falling clock counter
    localparam MAX_FALL_CYCLES = 20;
    reg [3:0] fall_counter;
    always @(posedge clk, posedge areset) begin
        if (areset) begin
            fall_counter <= 4'b0;
        end else if (state == FALL) begin
            fall_counter <= fall_counter + 1;
        end else begin
            fall_counter <= 4'b0;
        end
