    input data,
    output reg [3:0] count,
    output reg counting,
    output reg done,
    input ack
);

    parameter IDLE = 2'b00;
    parameter SEARCH = 2'b01;
    parameter COUNTING = 2'b10;

    reg [1:0] state;
    reg [3:0] delay;
    reg [13:0] counter;

    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            delay <= 4'b0000;
            counter <= 14'b00000000000000;
            count <= 4'b0000;
            counting <= 1'b0;
            done <= 1'b0;
        end
        else begin
            case (state)
                IDLE: begin
                    if (data == 1'b1) begin
                        state <= SEARCH;
                    end
                end
                SEARCH: begin
                    if (data == 1'b1) begin
                        if (data == 1'b0) begin
                            state <= IDLE;
                        end
                    end
                    else begin
                        state <= IDLE;
                    end
                end
                COUNTING: begin
                    if (counter == 14'b00000000000000) begin
                        counting <= 1'b0;
                        done <= 1'b1;
                        state <= IDLE;
                    end
                    else begin
                        counter <= counter - 1;
                        count <= delay - counter[13:10];
                    end
                end
            endcase

            case (state)
                IDLE: begin
                    count <= 4'b0000;
                    counting <= 1'b0;
                    done <= 1'b0;
                end
                SEARCH: begin
                    if (data == 1'b1) begin
                        delay <= {data, delay[3:1]};
                        if (delay == 4'b1101) begin
                            counting <= 1'b1;
                            counter <= (delay + 1) * 1000;
                            state <= COUNTING;
                        end
                    end
                end
            endcase
        end
    end

endmodule

module TopModule(
    input clk,
    input reset,
    input data,
    output reg [3:0] count,
    output reg counting,
    output reg done,
    input ack
);

    reg [3:0] delay;
    reg [3:0] counter;
    reg [1:0] state;

    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
            counting <= 1'b0;
            done <= 1'b0;
            delay <= 4'b0000;
            counter <= 4'b0000;
            count <= 4'b0000;
        end else begin
            case (state)
                2'b00: begin // idle state
                    if (data == 1'b1 && count == 4'b1101) begin
                        state <= 2'b01;
                    end
                end
                2'b01: begin // delay state
                    if (counter == 4'b1111) begin
                        state <= 2'b10;
                        delay <= data;
                        counter <= 4'b0000;
                        counting <= 1'b1;
                    end else begin
                        counter <= counter + 1;
                    end
                end
                2'b10: begin // count state
                    if (counter == 4'b1111) begin
                        state <= 2'b00;
                        counting <= 1'b0;
                        done <= 1'b1;
                        counter <= 4'b0000;
                        count <= delay;
                    end else begin
                        counter <= counter + 1;
                        count <= delay - counter;
                    end
                end
            endcase
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
            counting <= 1'b0;
            done <= 1'b0;
            delay <= 4'b0000;
            counter <= 4'b0000;
            count <= 4'b0000;
        end else begin
            if (state == 2'b10) begin
                if (ack) begin
                    state <= 2'b00;
                    done <= 1'b0;
                end
            end
        end
    end

endmodule
